('babc3e6e-8b3d-41c7-a95a-823760d70f73', '5c93c785-bc3e-4489-969c-9ec5f21c174a', 'pyq', 'Eco ll - October 2025', 'Practice PYQs and Ace your Endsems.', '', 2025, 'https://h36y6svq.us-east.insforge.app/api/storage/buckets/cue-pyqs/objects/5c93c785-bc3e-4489-969c-9ec5f21c174a%2F2025%2Fa6184ac2-d643-4343-8979-910b1b0980bc-principles-of-economics-ii-october-2025.pdf?v=093337e454cc533ff923907e93ef0fac', '5c93c785-bc3e-4489-969c-9ec5f21c174a/2025/a6184ac2-d643-4343-8979-910b1b0980bc-principles-of-economics-ii-october-2025.pdf', 1, true, 'Regular Examination', 'Principles_of_Economics_II_October_2025.pdf', 38642, 'a6184ac2-d643-4343-8979-910b1b0980bc', NULL, NULL, NULL, NULL, '2026-09-17 08:24:47.23924+00', '2026-09-17 18:36:21.635816+00'),
('2e051408-6b6d-4653-ba9d-bde42d05fc9c', '4942b243-3eda-4100-9200-942a29e98d11', 'pyq', 'Equity and Debt Markets - October 2025', 'Practice PYQs and Ace your exams.', '', 2025, 'https://h36y6svq.us-east.insforge.app/api/storage/buckets/cue-pyqs/objects/4942b243-3eda-4100-9200-942a29e98d11%2F2025%2F250d2cc7-9fd7-424b-8584-6725258230d5-equity-and-debt-markets-october-2025.pdf?v=56d5f3ab703d6f7efba8a2d7328ae735', '4942b243-3eda-4100-9200-942a29e98d11/2025/250d2cc7-9fd7-424b-8584-6725258230d5-equity-and-debt-markets-october-2025.pdf', 1, true, 'Regular Examination', 'Equity_and_Debt_Markets_October_2025.pdf', 39035, '250d2cc7-9fd7-424b-8584-6725258230d5', NULL, NULL, NULL, NULL, '2026-09-17 08:23:17.754181+00', '2026-09-17 12:24:47.464114+00'),
('a58945e0-6041-4b04-b88d-eb429da2842c', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'State the important features of equity shares.', '', 'Ownership — represent part-ownership of the company
Voting rights — one share generally equals one vote
Variable/residual return — dividend is not fixed, declared only if profits allow
Permanent capital — not repayable during the company''s life (except via buyback)
Limited liability — liability restricted to amount unpaid on shares held
High risk, high return — no assured return, but higher long-term growth potential
Transferability — freely transferable on a stock exchange (for listed companies)

Exam Tip: Classic 4–6 mark "state the features" question — number your points clearly.', NULL, NULL, NULL, 2, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'dc365377-2a45-4a2b-9c54-b6feaa2aec58', '{"blocks": [{"id": "edm-u1-2-q-1", "text": "State the important features of equity shares.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-2-a-1", "type": "numberList", "items": ["Ownership — represent part-ownership of the company", "Voting rights — one share generally equals one vote", "Variable/residual return — dividend is not fixed, declared only if profits allow", "Permanent capital — not repayable during the company''s life (except via buyback)", "Limited liability — liability restricted to amount unpaid on shares held", "High risk, high return — no assured return, but higher long-term growth potential", "Transferability — freely transferable on a stock exchange (for listed companies)"]}, {"id": "edm-u1-2-a-2", "bold": true, "text": "Exam Tip: Classic 4–6 mark \"state the features\" question — number your points clearly.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('00b9db04-b5b2-4aa5-be71-d06f6d8c5a77', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', '"Explain the concept of Equity Share." (Long-answer structure)', '', 'Introduction: Equity share = unit of ownership capital
Definition: Part-ownership + residual claim + voting rights
Main body: Features → Rights of shareholders → Significance in corporate financing
Example: Any listed company''s ordinary share
Conclusion: Equity shares form the backbone of a company''s owned capital and of the equity market itself

Exam Tip: This structure (Intro → Definition → Features → Significance → Conclusion) reuses for almost any "Explain X" question in this unit.', NULL, NULL, NULL, 3, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'dc365377-2a45-4a2b-9c54-b6feaa2aec58', '{"blocks": [{"id": "edm-u1-3-q-1", "text": "\"Explain the concept of Equity Share.\" (Long-answer structure)", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-3-a-1", "type": "bulletList", "items": ["Introduction: Equity share = unit of ownership capital", "Definition: Part-ownership + residual claim + voting rights", "Main body: Features → Rights of shareholders → Significance in corporate financing", "Example: Any listed company''s ordinary share", "Conclusion: Equity shares form the backbone of a company''s owned capital and of the equity market itself"]}, {"id": "edm-u1-3-a-2", "bold": true, "text": "Exam Tip: This structure (Intro → Definition → Features → Significance → Conclusion) reuses for almost any \"Explain X\" question in this unit.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('76494b72-8a65-446f-a2e3-9423e8550d04', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Distinguish between Equity Shares and Preference Shares.', '', 'Basis | Equity Share | Preference Share
Dividend | Variable, not guaranteed | Fixed rate, priority in payment
Voting Right | Normally available | Normally none
Claim on Assets | After all other claims (residual) | Before equity shareholders
Risk | Higher | Lower (relative to equity)

Common Trap: Not one of the 10 mandatory Unit 1 points — supplementary background only.', NULL, NULL, NULL, 4, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'dc365377-2a45-4a2b-9c54-b6feaa2aec58', '{"blocks": [{"id": "edm-u1-4-q-1", "text": "Distinguish between Equity Shares and Preference Shares.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-4-a-1", "rows": [["Basis", "Equity Share", "Preference Share"], ["Dividend", "Variable, not guaranteed", "Fixed rate, priority in payment"], ["Voting Right", "Normally available", "Normally none"], ["Claim on Assets", "After all other claims (residual)", "Before equity shareholders"], ["Risk", "Higher", "Lower (relative to equity)"]], "type": "table"}, {"id": "edm-u1-4-a-2", "bold": true, "text": "Common Trap: Not one of the 10 mandatory Unit 1 points — supplementary background only.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('0c018364-4a15-422b-8402-6d98a35d8f91', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Explain the relationship between the growth of the corporate sector and the growth of equity shareholders in India.', '', 'As India''s corporate sector expanded (more companies, larger capital requirements, industrialisation, liberalisation post-1991), companies increasingly turned to public equity capital instead of relying only on promoter funds or debt. Two-way growth loop:

More companies → more shares issued → more investment opportunities
More investor awareness and participation → deeper capital markets → easier future fundraising for companies

Exam Tip: Mention liberalisation (1991 reforms) and the shift from promoter-controlled base to broad public shareholder base.', NULL, NULL, NULL, 5, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '831aa97e-639e-45e0-b1b6-01cedf21cb9a', '{"blocks": [{"id": "edm-u1-5-q-1", "text": "Explain the relationship between the growth of the corporate sector and the growth of equity shareholders in India.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-5-a-1", "text": "As India''s corporate sector expanded (more companies, larger capital requirements, industrialisation, liberalisation post-1991), companies increasingly turned to public equity capital instead of relying only on promoter funds or debt. Two-way growth loop:", "type": "text", "style": "paragraph"}, {"id": "edm-u1-5-a-2", "type": "bulletList", "items": ["More companies → more shares issued → more investment opportunities", "More investor awareness and participation → deeper capital markets → easier future fundraising for companies"]}, {"id": "edm-u1-5-a-3", "bold": true, "text": "Exam Tip: Mention liberalisation (1991 reforms) and the shift from promoter-controlled base to broad public shareholder base.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('b4772bd8-22d8-406e-9053-e444204a069b', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Short note: Factors contributing to the growth of the corporate sector in India.', '', 'Economic liberalisation and industrial policy reforms
Growth of capital markets and institutional investors
Rising domestic savings channelled into equity
Government disinvestment and IPOs of public sector units
Increased financial literacy and access via technology (demat, online trading)', NULL, NULL, NULL, 6, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '831aa97e-639e-45e0-b1b6-01cedf21cb9a', '{"blocks": [{"id": "edm-u1-6-q-1", "text": "Short note: Factors contributing to the growth of the corporate sector in India.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-6-a-1", "type": "bulletList", "items": ["Economic liberalisation and industrial policy reforms", "Growth of capital markets and institutional investors", "Rising domestic savings channelled into equity", "Government disinvestment and IPOs of public sector units", "Increased financial literacy and access via technology (demat, online trading)"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('37170cdd-2b8d-4de4-896f-ca635b915577', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Why does a wider shareholder base matter for a growing corporate sector?', '', 'A wider shareholder base spreads business risk across many investors instead of concentrating it with a few promoters, gives companies cheaper and more diversified access to capital, and deepens overall market liquidity — attracting further corporate listings and reinforcing the growth cycle.', NULL, NULL, NULL, 7, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '831aa97e-639e-45e0-b1b6-01cedf21cb9a', '{"blocks": [{"id": "edm-u1-7-q-1", "text": "Why does a wider shareholder base matter for a growing corporate sector?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-7-a-1", "text": "A wider shareholder base spreads business risk across many investors instead of concentrating it with a few promoters, gives companies cheaper and more diversified access to capital, and deepens overall market liquidity — attracting further corporate listings and reinforcing the growth cycle.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('3b44189d-6c39-44ce-a6fc-34f9c2ff81b7', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Explain the separation between ownership and management in a company.', '', 'In a joint-stock company, ownership (equity shareholders) is legally and practically separated from management (Board of Directors and executives). Shareholders own the company but do not directly manage it; they elect directors to act on their behalf. This allows companies to raise capital from thousands of investors who need not have managerial expertise. Exam Tip: Always link to "professional management" and "agency relationship."', NULL, NULL, NULL, 8, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '02d68caf-b602-4024-8364-47554e211d41', '{"blocks": [{"id": "edm-u1-8-q-1", "text": "Explain the separation between ownership and management in a company.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-8-a-1", "text": "In a joint-stock company, ownership (equity shareholders) is legally and practically separated from management (Board of Directors and executives). Shareholders own the company but do not directly manage it; they elect directors to act on their behalf. This allows companies to raise capital from thousands of investors who need not have managerial expertise. Exam Tip: Always link to \"professional management\" and \"agency relationship.\"", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('08ebdc35-8aa0-40f3-abb5-fdca45e54565', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'What is meant by corporate governance?', '', 'Corporate governance is the system of rules, practices, and processes by which a company is directed and controlled, balancing the interests of shareholders, management, the board, and other stakeholders. Aims to ensure transparency, accountability, and fairness.', NULL, NULL, NULL, 9, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '02d68caf-b602-4024-8364-47554e211d41', '{"blocks": [{"id": "edm-u1-9-q-1", "text": "What is meant by corporate governance?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-9-a-1", "text": "Corporate governance is the system of rules, practices, and processes by which a company is directed and controlled, balancing the interests of shareholders, management, the board, and other stakeholders. Aims to ensure transparency, accountability, and fairness.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('562da747-86fc-4c66-9c56-6b8cb7ba343e', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'State the key components/pillars of a good corporate governance framework.', '', 'Board of Directors — oversight and strategic direction
Transparency & disclosure — timely, accurate reporting to shareholders
Accountability — management answerable to the board; board answerable to shareholders
Shareholder rights — voting, information, participation
Regulatory compliance — SEBI/Companies Act norms for listed companies', NULL, NULL, NULL, 10, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '02d68caf-b602-4024-8364-47554e211d41', '{"blocks": [{"id": "edm-u1-10-q-1", "text": "State the key components/pillars of a good corporate governance framework.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-10-a-1", "type": "numberList", "items": ["Board of Directors — oversight and strategic direction", "Transparency & disclosure — timely, accurate reporting to shareholders", "Accountability — management answerable to the board; board answerable to shareholders", "Shareholder rights — voting, information, participation", "Regulatory compliance — SEBI/Companies Act norms for listed companies"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('32ec1d41-4a05-45b5-84fb-500e7612270a', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Explain the relationship between ownership, management, and governance in a company. (Long-answer structure)', '', 'Introduction: Ownership (shareholders) and management (executives) are distinct groups
Ownership: Shareholders supply capital and bear residual risk; elect the board
Management: Board and executives run operations on shareholders'' behalf
Governance link: Keeps management accountable to owners, preventing misuse of shareholder capital (the "agency problem")
Conclusion: Strong governance makes the separation of ownership and management workable and trustworthy for investors

Exam Tip: Ownership → delegated to → Management → kept accountable by → Governance.', NULL, NULL, NULL, 11, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '02d68caf-b602-4024-8364-47554e211d41', '{"blocks": [{"id": "edm-u1-11-q-1", "text": "Explain the relationship between ownership, management, and governance in a company. (Long-answer structure)", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-11-a-1", "type": "bulletList", "items": ["Introduction: Ownership (shareholders) and management (executives) are distinct groups", "Ownership: Shareholders supply capital and bear residual risk; elect the board", "Management: Board and executives run operations on shareholders'' behalf", "Governance link: Keeps management accountable to owners, preventing misuse of shareholder capital (the \"agency problem\")", "Conclusion: Strong governance makes the separation of ownership and management workable and trustworthy for investors"]}, {"id": "edm-u1-11-a-2", "bold": true, "text": "Exam Tip: Ownership → delegated to → Management → kept accountable by → Governance.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('14b5bfbb-f38d-41ca-9391-5627e93adb25', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Why do students often wrongly assume shareholders manage the company?', '', 'Common Trap: Shareholders'' control is largely indirect — exercised through voting at general meetings and electing directors, not through running the business themselves.', NULL, NULL, NULL, 12, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '02d68caf-b602-4024-8364-47554e211d41', '{"blocks": [{"id": "edm-u1-12-q-1", "text": "Why do students often wrongly assume shareholders manage the company?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-12-a-1", "bold": true, "text": "Common Trap: Shareholders'' control is largely indirect — exercised through voting at general meetings and electing directors, not through running the business themselves.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('27188d05-40a7-4a62-beef-fe6ca6e2979c', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'What do you understand by "equity culture"?', '', 'The extent to which the general public treats equity shares as a normal, trusted, widely used investment/savings option — rather than a niche or speculative activity. A strong equity culture means broad-based retail participation, financial literacy, and public trust in market institutions.', NULL, NULL, NULL, 13, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '348a4bf4-c2e4-4f05-9ea1-2e74a0ca8c1d', '{"blocks": [{"id": "edm-u1-13-q-1", "text": "What do you understand by \"equity culture\"?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-13-a-1", "text": "The extent to which the general public treats equity shares as a normal, trusted, widely used investment/savings option — rather than a niche or speculative activity. A strong equity culture means broad-based retail participation, financial literacy, and public trust in market institutions.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('1033694a-978b-414c-b070-a757ac0ece9a', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Trace the broad development of equity culture in India.', '', 'Pre-1990s: Narrow, promoter/HNI-driven participation
Post-1991 liberalisation: Capital market reforms, entry of FIIs, growth of stock exchanges (NSE established 1992)
SEBI-led reforms (1990s–2000s): Investor protection, dematerialisation, screen-based trading
2000s–2010s: Mutual funds and SIPs popularise indirect equity investment
2010s–present: Technology-driven access, rising demat accounts, growing retail direct participation

Exam Tip: As a numbered timeline, converts easily into a short note or "discuss the development" answer.', NULL, NULL, NULL, 14, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '348a4bf4-c2e4-4f05-9ea1-2e74a0ca8c1d', '{"blocks": [{"id": "edm-u1-14-q-1", "text": "Trace the broad development of equity culture in India.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-14-a-1", "type": "numberList", "items": ["Pre-1990s: Narrow, promoter/HNI-driven participation", "Post-1991 liberalisation: Capital market reforms, entry of FIIs, growth of stock exchanges (NSE established 1992)", "SEBI-led reforms (1990s–2000s): Investor protection, dematerialisation, screen-based trading", "2000s–2010s: Mutual funds and SIPs popularise indirect equity investment", "2010s–present: Technology-driven access, rising demat accounts, growing retail direct participation"]}, {"id": "edm-u1-14-a-2", "bold": true, "text": "Exam Tip: As a numbered timeline, converts easily into a short note or \"discuss the development\" answer.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('4acbfb8d-0e4c-4ba5-9e7a-9a6d3b0504b4', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Discuss the current position of equity culture in India.', '', 'Rapidly growing base of retail equity investors, supported by rising demat account numbers, growth of SIPs into equity mutual funds, and technology-enabled discount broking. Equity participation as a share of household savings, while growing, is still developing compared to more mature markets. Exam Tip: Write directionally ("growing," "rising") rather than quoting unverified statistics.', NULL, NULL, NULL, 15, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '348a4bf4-c2e4-4f05-9ea1-2e74a0ca8c1d', '{"blocks": [{"id": "edm-u1-15-q-1", "text": "Discuss the current position of equity culture in India.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-15-a-1", "text": "Rapidly growing base of retail equity investors, supported by rising demat account numbers, growth of SIPs into equity mutual funds, and technology-enabled discount broking. Equity participation as a share of household savings, while growing, is still developing compared to more mature markets. Exam Tip: Write directionally (\"growing,\" \"rising\") rather than quoting unverified statistics.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('bdaf9196-8597-4bd2-8f98-c0b283682dfc', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Why is a strong equity culture important for a developing economy like India?', '', 'Channels household savings into productive corporate investment, provides long-term growth capital, supports capital formation, and gives citizens a stake in economic growth.', NULL, NULL, NULL, 16, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '348a4bf4-c2e4-4f05-9ea1-2e74a0ca8c1d', '{"blocks": [{"id": "edm-u1-16-q-1", "text": "Why is a strong equity culture important for a developing economy like India?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-16-a-1", "text": "Channels household savings into productive corporate investment, provides long-term growth capital, supports capital formation, and gives citizens a stake in economic growth.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('36db8637-1740-45fc-b5cb-1c5ddd783dc8', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'What is a Demat (Dematerialised) Account?', '', 'An account that holds an investor''s securities (shares, bonds, mutual fund units) in electronic form, eliminating the need for physical share certificates — like a "bank account for securities."', NULL, NULL, NULL, 17, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '109a551f-d6a7-41fd-8c2f-370630a05dbd', '{"blocks": [{"id": "edm-u1-17-q-1", "text": "What is a Demat (Dematerialised) Account?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-17-a-1", "text": "An account that holds an investor''s securities (shares, bonds, mutual fund units) in electronic form, eliminating the need for physical share certificates — like a \"bank account for securities.\"", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('7ad5b832-7abf-4dbd-bc4e-47350b8a1490', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'What is a Trading Account?', '', 'An account opened with a stockbroker that allows an investor to place buy/sell orders on the stock exchange — the account through which order execution happens.', NULL, NULL, NULL, 18, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '109a551f-d6a7-41fd-8c2f-370630a05dbd', '{"blocks": [{"id": "edm-u1-18-q-1", "text": "What is a Trading Account?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-18-a-1", "text": "An account opened with a stockbroker that allows an investor to place buy/sell orders on the stock exchange — the account through which order execution happens.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('83d6800a-00cb-4e0f-873b-4ac15146ae57', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'What is a Depository? Name the depositories in India.', '', 'An institution that holds securities in electronic (dematerialised) form on behalf of investors and facilitates their transfer. India has two depositories:

NSDL (National Securities Depository Limited)
CDSL (Central Depository Services Limited)', NULL, NULL, NULL, 19, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '109a551f-d6a7-41fd-8c2f-370630a05dbd', '{"blocks": [{"id": "edm-u1-19-q-1", "text": "What is a Depository? Name the depositories in India.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-19-a-1", "text": "An institution that holds securities in electronic (dematerialised) form on behalf of investors and facilitates their transfer. India has two depositories:", "type": "text", "style": "paragraph"}, {"id": "edm-u1-19-a-2", "type": "bulletList", "items": ["NSDL (National Securities Depository Limited)", "CDSL (Central Depository Services Limited)"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('b996bae0-55b3-4100-8c5b-50cb2f5fc6c4', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'What is a Depository Participant?', '', 'An agent of the depository (e.g., a bank or broker registered with NSDL/CDSL) that acts as the link between the investor and the depository. Investors open a Demat Account through a DP, not directly with the depository.', NULL, NULL, NULL, 20, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '109a551f-d6a7-41fd-8c2f-370630a05dbd', '{"blocks": [{"id": "edm-u1-20-q-1", "text": "What is a Depository Participant?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-20-a-1", "text": "An agent of the depository (e.g., a bank or broker registered with NSDL/CDSL) that acts as the link between the investor and the depository. Investors open a Demat Account through a DP, not directly with the depository.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('20889dab-f0ff-46a1-a488-af76dd1ee6d0', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Explain the practical transaction flow when an investor buys shares.', '', 'Investor opens a Trading Account (with a broker) and a Demat Account (through a DP)
Investor places a buy order through the Trading Account on the stock exchange
Order is matched and executed
Funds are debited from the investor''s linked bank account
Purchased shares are credited to the investor''s Demat Account, via the Depository (NSDL/CDSL) and the DP
On selling, the reverse flow happens

Exam Tip: Strong candidate for a "process/flow-based" question — practice as a numbered flow.', NULL, NULL, NULL, 21, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '109a551f-d6a7-41fd-8c2f-370630a05dbd', '{"blocks": [{"id": "edm-u1-21-q-1", "text": "Explain the practical transaction flow when an investor buys shares.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-21-a-1", "type": "numberList", "items": ["Investor opens a Trading Account (with a broker) and a Demat Account (through a DP)", "Investor places a buy order through the Trading Account on the stock exchange", "Order is matched and executed", "Funds are debited from the investor''s linked bank account", "Purchased shares are credited to the investor''s Demat Account, via the Depository (NSDL/CDSL) and the DP", "On selling, the reverse flow happens"]}, {"id": "edm-u1-21-a-2", "bold": true, "text": "Exam Tip: Strong candidate for a \"process/flow-based\" question — practice as a numbered flow.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('68626229-7b20-4dbe-a0e3-78edd238549d', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Differentiate between a Demat Account and a Trading Account.', '', 'Basis | Demat Account | Trading Account
Purpose | Holds securities electronically | Executes buy/sell orders
Opened With | Depository Participant (DP) | Stockbroker
Function | Storage/custody of securities | Transaction execution
Analogy | "Locker" for shares | "Gateway" for trading

Exam Tip: One of the highest-probability comparison questions in the unit — memorise precisely.', NULL, NULL, NULL, 22, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '109a551f-d6a7-41fd-8c2f-370630a05dbd', '{"blocks": [{"id": "edm-u1-22-q-1", "text": "Differentiate between a Demat Account and a Trading Account.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-22-a-1", "rows": [["Basis", "Demat Account", "Trading Account"], ["Purpose", "Holds securities electronically", "Executes buy/sell orders"], ["Opened With", "Depository Participant (DP)", "Stockbroker"], ["Function", "Storage/custody of securities", "Transaction execution"], ["Analogy", "\"Locker\" for shares", "\"Gateway\" for trading"]], "type": "table"}, {"id": "edm-u1-22-a-2", "bold": true, "text": "Exam Tip: One of the highest-probability comparison questions in the unit — memorise precisely.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('90c84e6c-57f5-46fa-9e21-afc189dd6bb0', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'How are the Demat Account, Trading Account, and Depository related to each other?', '', 'Integrated system: the Trading Account initiates the transaction, the Depository (via the DP) provides the electronic infrastructure to hold and transfer ownership, and the Demat Account is where the resulting securities sit. All three must work together.', NULL, NULL, NULL, 23, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '109a551f-d6a7-41fd-8c2f-370630a05dbd', '{"blocks": [{"id": "edm-u1-23-q-1", "text": "How are the Demat Account, Trading Account, and Depository related to each other?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-23-a-1", "text": "Integrated system: the Trading Account initiates the transaction, the Depository (via the DP) provides the electronic infrastructure to hold and transfer ownership, and the Demat Account is where the resulting securities sit. All three must work together.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('7aad0220-5766-4080-b43b-5a2eb71886f4', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Common confusion — Demat Account vs Depository vs DP.', '', 'Common Trap: The Depository (NSDL/CDSL) is the institution; the DP is the intermediary through whom you access it; the Demat Account is your individual account held via that DP.', NULL, NULL, NULL, 24, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '109a551f-d6a7-41fd-8c2f-370630a05dbd', '{"blocks": [{"id": "edm-u1-24-q-1", "text": "Common confusion — Demat Account vs Depository vs DP.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-24-a-1", "bold": true, "text": "Common Trap: The Depository (NSDL/CDSL) is the institution; the DP is the intermediary through whom you access it; the Demat Account is your individual account held via that DP.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('85524281-f6e8-46f4-9ea1-ca7be04cd117', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Define the Money Market.', '', 'The market for short-term funds, typically maturities of up to one year. Deals in Treasury Bills, Commercial Paper, Certificates of Deposit, and Call Money; used for managing short-term liquidity.', NULL, NULL, NULL, 25, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'f783eb9f-7eaf-44d7-8ae3-78c00b932fa9', '{"blocks": [{"id": "edm-u1-25-q-1", "text": "Define the Money Market.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-25-a-1", "text": "The market for short-term funds, typically maturities of up to one year. Deals in Treasury Bills, Commercial Paper, Certificates of Deposit, and Call Money; used for managing short-term liquidity.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('b06bf904-60c7-44e4-a5c5-a6787acb0e6a', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Define the Debt Market.', '', 'The market (or Bond Market) where long-term debt instruments — government securities, corporate bonds, debentures — are issued and traded. Investors lend money for a fixed period in exchange for periodic interest and repayment of principal at maturity.', NULL, NULL, NULL, 26, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'f783eb9f-7eaf-44d7-8ae3-78c00b932fa9', '{"blocks": [{"id": "edm-u1-26-q-1", "text": "Define the Debt Market.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-26-a-1", "text": "The market (or Bond Market) where long-term debt instruments — government securities, corporate bonds, debentures — are issued and traded. Investors lend money for a fixed period in exchange for periodic interest and repayment of principal at maturity.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('66606800-ecb1-4d90-934c-7468a93721c9', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Distinguish between the Money Market and the Debt Market.', '', 'Basis | Money Market | Debt Market
Maturity | Short-term (up to 1 year) | Medium-to-long term (beyond 1 year)
Instruments | T-Bills, Commercial Paper, Call Money, CDs | G-Secs, corporate bonds, debentures
Purpose | Liquidity management | Long-term capital raising
Risk | Generally low | Varies (higher for corporate, lower for G-Secs)
Participants | Banks, RBI, large corporates | Governments, corporates, institutional & retail investors

Exam Tip: The single most likely "differentiate" question in Unit 1. Related but distinct — money market is often a segment of the broader debt market.', NULL, NULL, NULL, 27, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'f783eb9f-7eaf-44d7-8ae3-78c00b932fa9', '{"blocks": [{"id": "edm-u1-27-q-1", "text": "Distinguish between the Money Market and the Debt Market.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-27-a-1", "rows": [["Basis", "Money Market", "Debt Market"], ["Maturity", "Short-term (up to 1 year)", "Medium-to-long term (beyond 1 year)"], ["Instruments", "T-Bills, Commercial Paper, Call Money, CDs", "G-Secs, corporate bonds, debentures"], ["Purpose", "Liquidity management", "Long-term capital raising"], ["Risk", "Generally low", "Varies (higher for corporate, lower for G-Secs)"], ["Participants", "Banks, RBI, large corporates", "Governments, corporates, institutional & retail investors"]], "type": "table"}, {"id": "edm-u1-27-a-2", "bold": true, "text": "Exam Tip: The single most likely \"differentiate\" question in Unit 1. Related but distinct — money market is often a segment of the broader debt market.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('1d3e2385-e08b-4b89-985f-04ca6892738c', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Explain how the money market and debt market are related.', '', 'Both are markets for borrowed funds (unlike the equity market). The money market can be viewed as the short-term segment of the broader debt market ecosystem — together spanning overnight liquidity needs to long-term capital projects.', NULL, NULL, NULL, 28, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'f783eb9f-7eaf-44d7-8ae3-78c00b932fa9', '{"blocks": [{"id": "edm-u1-28-q-1", "text": "Explain how the money market and debt market are related.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-28-a-1", "text": "Both are markets for borrowed funds (unlike the equity market). The money market can be viewed as the short-term segment of the broader debt market ecosystem — together spanning overnight liquidity needs to long-term capital projects.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('acb748f4-79d2-4d52-ac4b-37f2008deae6', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Explain the structure of debt markets in India. (Long-answer structure)', '', 'Introduction: Debt markets facilitate borrowing/lending of long-term funds through tradable instruments
Segments: Government Securities market (largest) and Corporate Bond market
Instruments: G-Secs, State Development Loans, PSU bonds, corporate debentures
Participants: RBI (G-Secs), SEBI-regulated intermediaries (corporate bonds), banks, insurance companies, mutual funds
Conclusion: Dominated by government securities; corporate bond segment still developing relative to global markets', NULL, NULL, NULL, 29, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'f783eb9f-7eaf-44d7-8ae3-78c00b932fa9', '{"blocks": [{"id": "edm-u1-29-q-1", "text": "Explain the structure of debt markets in India. (Long-answer structure)", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-29-a-1", "type": "bulletList", "items": ["Introduction: Debt markets facilitate borrowing/lending of long-term funds through tradable instruments", "Segments: Government Securities market (largest) and Corporate Bond market", "Instruments: G-Secs, State Development Loans, PSU bonds, corporate debentures", "Participants: RBI (G-Secs), SEBI-regulated intermediaries (corporate bonds), banks, insurance companies, mutual funds", "Conclusion: Dominated by government securities; corporate bond segment still developing relative to global markets"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('16ba907d-23e4-45fa-bb47-b544d7385b86', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Trace the evolution of debt markets in India.', '', 'Pre-reform era (before 1990s): Government borrowing at administered rates; limited private participation
1990s reforms: Market-determined interest rates; auction-based systems for G-Secs
RBI-led infrastructure: Negotiated Dealing System (NDS), CCIL for settlement
2000s onward: Growth of corporate bond market, SEBI regulations, electronic trading platforms
Recent developments: Deepening corporate bond market, green/ESG-linked bonds

Exam Tip: "From administered rates to a market-driven, electronically-settled system."', NULL, NULL, NULL, 30, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '05f497c8-4aca-49d4-b544-c7e67463e777', '{"blocks": [{"id": "edm-u1-30-q-1", "text": "Trace the evolution of debt markets in India.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-30-a-1", "type": "numberList", "items": ["Pre-reform era (before 1990s): Government borrowing at administered rates; limited private participation", "1990s reforms: Market-determined interest rates; auction-based systems for G-Secs", "RBI-led infrastructure: Negotiated Dealing System (NDS), CCIL for settlement", "2000s onward: Growth of corporate bond market, SEBI regulations, electronic trading platforms", "Recent developments: Deepening corporate bond market, green/ESG-linked bonds"]}, {"id": "edm-u1-30-a-2", "bold": true, "text": "Exam Tip: \"From administered rates to a market-driven, electronically-settled system.\"", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('1283366c-0ce1-4c19-93d8-a70e00f67f93', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Why did India''s debt markets need reform after the 1990s?', '', 'Administratively fixed interest rates discouraged genuine price discovery and limited market depth. Reforms introduced auction-based pricing, better settlement infrastructure, and regulatory oversight — more transparent, efficient, and attractive to a wider range of investors.', NULL, NULL, NULL, 31, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '05f497c8-4aca-49d4-b544-c7e67463e777', '{"blocks": [{"id": "edm-u1-31-q-1", "text": "Why did India''s debt markets need reform after the 1990s?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-31-a-1", "text": "Administratively fixed interest rates discouraged genuine price discovery and limited market depth. Reforms introduced auction-based pricing, better settlement infrastructure, and regulatory oversight — more transparent, efficient, and attractive to a wider range of investors.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('027545db-641c-498d-9bcc-5b32cb69f449', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Short note: Key institutional developments in the Indian debt market.', '', 'Auction-based issuance of government securities
Establishment of the Clearing Corporation of India Ltd. (CCIL)
Negotiated Dealing System (NDS) for electronic trading of G-Secs
Progressive SEBI regulation of the corporate bond market', NULL, NULL, NULL, 32, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '05f497c8-4aca-49d4-b544-c7e67463e777', '{"blocks": [{"id": "edm-u1-32-q-1", "text": "Short note: Key institutional developments in the Indian debt market.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-32-a-1", "type": "bulletList", "items": ["Auction-based issuance of government securities", "Establishment of the Clearing Corporation of India Ltd. (CCIL)", "Negotiated Dealing System (NDS) for electronic trading of G-Secs", "Progressive SEBI regulation of the corporate bond market"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('884ad387-3d73-4a42-b254-5b49a3ade16a', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'How does the evolution of the debt market explain today''s regulatory structure?', '', 'Government securities and corporate debt evolved through different reform tracks, giving India a dual regulatory structure: RBI oversees government securities/money market; SEBI oversees corporate bonds/intermediaries.', NULL, NULL, NULL, 33, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '05f497c8-4aca-49d4-b544-c7e67463e777', '{"blocks": [{"id": "edm-u1-33-q-1", "text": "How does the evolution of the debt market explain today''s regulatory structure?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-33-a-1", "text": "Government securities and corporate debt evolved through different reform tracks, giving India a dual regulatory structure: RBI oversees government securities/money market; SEBI oversees corporate bonds/intermediaries.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('5bba3c03-4030-4c58-91db-34b16632a9cd', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Why is regulation necessary in the debt market?', '', 'Ensures investor protection, fair pricing/price discovery, transparency, and systemic stability — poor regulation here can have economy-wide consequences given links to monetary policy and government borrowing costs.', NULL, NULL, NULL, 34, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '53331794-37a3-4e2a-a706-538e6d183612', '{"blocks": [{"id": "edm-u1-34-q-1", "text": "Why is regulation necessary in the debt market?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-34-a-1", "text": "Ensures investor protection, fair pricing/price discovery, transparency, and systemic stability — poor regulation here can have economy-wide consequences given links to monetary policy and government borrowing costs.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('03da412f-00dc-44e0-bf43-da380dcc8c78', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'State the key elements of the regulatory framework governing India''s debt market.', '', 'Dual regulatory oversight — RBI (G-Secs, money market) and SEBI (corporate bonds, intermediaries)
Issuance rules — disclosure and credit-rating requirements
Trading & settlement infrastructure — regulated exchanges/platforms, CCIL
Investor protection norms — disclosure, grievance redressal', NULL, NULL, NULL, 35, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '53331794-37a3-4e2a-a706-538e6d183612', '{"blocks": [{"id": "edm-u1-35-q-1", "text": "State the key elements of the regulatory framework governing India''s debt market.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-35-a-1", "type": "numberList", "items": ["Dual regulatory oversight — RBI (G-Secs, money market) and SEBI (corporate bonds, intermediaries)", "Issuance rules — disclosure and credit-rating requirements", "Trading & settlement infrastructure — regulated exchanges/platforms, CCIL", "Investor protection norms — disclosure, grievance redressal"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('89a380a4-868b-4984-bea8-9155a428e37f', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Explain the regulatory framework of the Indian debt market. (Long-answer structure)', '', 'Introduction: Regulation split between two apex regulators
RBI''s domain: Government securities, money market instruments
SEBI''s domain: Corporate bonds, intermediaries, listing & disclosure norms
Supporting infrastructure: CCIL for settlement, credit rating agencies
Conclusion: Balances monetary stability with investor protection and market development', NULL, NULL, NULL, 36, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '53331794-37a3-4e2a-a706-538e6d183612', '{"blocks": [{"id": "edm-u1-36-q-1", "text": "Explain the regulatory framework of the Indian debt market. (Long-answer structure)", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-36-a-1", "type": "bulletList", "items": ["Introduction: Regulation split between two apex regulators", "RBI''s domain: Government securities, money market instruments", "SEBI''s domain: Corporate bonds, intermediaries, listing & disclosure norms", "Supporting infrastructure: CCIL for settlement, credit rating agencies", "Conclusion: Balances monetary stability with investor protection and market development"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('7ab5ac30-195b-4757-955a-96a8ffe95419', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Common trap — "SEBI regulates the debt market."', '', 'Common Trap: Precisely: SEBI regulates corporate debt securities and market intermediaries; RBI regulates government securities and the money market.', NULL, NULL, NULL, 37, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '53331794-37a3-4e2a-a706-538e6d183612', '{"blocks": [{"id": "edm-u1-37-q-1", "text": "Common trap — \"SEBI regulates the debt market.\"", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-37-a-1", "bold": true, "text": "Common Trap: Precisely: SEBI regulates corporate debt securities and market intermediaries; RBI regulates government securities and the money market.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('f936d166-fc0f-4b8f-bcc9-00417beadca4', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Explain the role of RBI in the Indian debt market.', '', 'Regulates and manages issuance of G-Secs and Treasury Bills
Conducts Open Market Operations (OMO)
Regulates money market instruments (Call Money, CPs, CDs)
Acts as debt manager to the Government
Maintains monetary and financial stability', NULL, NULL, NULL, 38, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '7539387d-acf0-4d2d-8563-2caba8a17d99', '{"blocks": [{"id": "edm-u1-38-q-1", "text": "Explain the role of RBI in the Indian debt market.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-38-a-1", "type": "bulletList", "items": ["Regulates and manages issuance of G-Secs and Treasury Bills", "Conducts Open Market Operations (OMO)", "Regulates money market instruments (Call Money, CPs, CDs)", "Acts as debt manager to the Government", "Maintains monetary and financial stability"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('b2d2aa0d-a124-427c-9fb4-b03423ccb4de', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Explain the role of SEBI in the Indian debt market.', '', 'Regulates the corporate bond market — issuance, listing, disclosure
Regulates market intermediaries dealing in debt securities
Protects investor interests through disclosure and grievance redressal
Promotes development of the corporate bond market', NULL, NULL, NULL, 39, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '7539387d-acf0-4d2d-8563-2caba8a17d99', '{"blocks": [{"id": "edm-u1-39-q-1", "text": "Explain the role of SEBI in the Indian debt market.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-39-a-1", "type": "bulletList", "items": ["Regulates the corporate bond market — issuance, listing, disclosure", "Regulates market intermediaries dealing in debt securities", "Protects investor interests through disclosure and grievance redressal", "Promotes development of the corporate bond market"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('1ed026b1-2ddc-45cb-86ec-4a7a1793af15', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Explain the role of Clearing Corporations (e.g., CCIL) in the debt market.', '', 'Act as a central counterparty, guaranteeing settlement even if one party defaults
Provide clearing/settlement infrastructure for G-Secs and money market trades
Reduce counterparty/settlement risk
Improve market efficiency through standardised settlement', NULL, NULL, NULL, 40, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '7539387d-acf0-4d2d-8563-2caba8a17d99', '{"blocks": [{"id": "edm-u1-40-q-1", "text": "Explain the role of Clearing Corporations (e.g., CCIL) in the debt market.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-40-a-1", "type": "bulletList", "items": ["Act as a central counterparty, guaranteeing settlement even if one party defaults", "Provide clearing/settlement infrastructure for G-Secs and money market trades", "Reduce counterparty/settlement risk", "Improve market efficiency through standardised settlement"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('0e5bf302-d113-44e2-9a11-662abb208f0e', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Differentiate between the roles of SEBI, RBI, and Clearing Corporations in the debt market.', '', 'Institution | Primary Domain | Core Role
RBI | Government securities, money market | Issuance, monetary policy, liquidity management
SEBI | Corporate bonds, intermediaries | Disclosure, investor protection, market development
Clearing Corp. (CCIL) | Settlement infrastructure | Guaranteed clearing & settlement, counterparty risk reduction

Exam Tip: Keep the three roles cleanly separated — don''t blend them.', NULL, NULL, NULL, 41, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '7539387d-acf0-4d2d-8563-2caba8a17d99', '{"blocks": [{"id": "edm-u1-41-q-1", "text": "Differentiate between the roles of SEBI, RBI, and Clearing Corporations in the debt market.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-41-a-1", "rows": [["Institution", "Primary Domain", "Core Role"], ["RBI", "Government securities, money market", "Issuance, monetary policy, liquidity management"], ["SEBI", "Corporate bonds, intermediaries", "Disclosure, investor protection, market development"], ["Clearing Corp. (CCIL)", "Settlement infrastructure", "Guaranteed clearing & settlement, counterparty risk reduction"]], "type": "table"}, {"id": "edm-u1-41-a-2", "bold": true, "text": "Exam Tip: Keep the three roles cleanly separated — don''t blend them.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('66d57da0-219e-4d65-a7a8-2c6298bac831', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', '"Discuss the role of regulatory bodies in the Indian debt market." (Long-answer structure)', '', 'Introduction: Multi-institution regulatory structure
RBI: issuance, OMO, money market regulation
SEBI: corporate bond regulation, disclosure, investor protection
Clearing Corporations: guaranteed settlement, counterparty risk reduction
Conclusion: Together ensure a well-regulated, transparent, settlement-safe debt market', NULL, NULL, NULL, 42, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '7539387d-acf0-4d2d-8563-2caba8a17d99', '{"blocks": [{"id": "edm-u1-42-q-1", "text": "\"Discuss the role of regulatory bodies in the Indian debt market.\" (Long-answer structure)", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-42-a-1", "type": "bulletList", "items": ["Introduction: Multi-institution regulatory structure", "RBI: issuance, OMO, money market regulation", "SEBI: corporate bond regulation, disclosure, investor protection", "Clearing Corporations: guaranteed settlement, counterparty risk reduction", "Conclusion: Together ensure a well-regulated, transparent, settlement-safe debt market"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('fdc98d04-fb61-40fc-bfd1-168b9468c536', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Common trap — treating RBI and SEBI''s roles as interchangeable.', '', 'Common Trap: RBI = government/money market; SEBI = corporate bonds/intermediaries. Mixing them up is a frequent reason marks are lost.', NULL, NULL, NULL, 43, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', '7539387d-acf0-4d2d-8563-2caba8a17d99', '{"blocks": [{"id": "edm-u1-43-q-1", "text": "Common trap — treating RBI and SEBI''s roles as interchangeable.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-43-a-1", "bold": true, "text": "Common Trap: RBI = government/money market; SEBI = corporate bonds/intermediaries. Mixing them up is a frequent reason marks are lost.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('785e2d5d-1b40-4794-90fb-bcfcc8d6000d', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'What is meant by ESG?', '', 'Environmental, Social, and Governance — a framework to evaluate a company''s/investment''s sustainability and ethical impact:

Environmental: climate impact, resource use, pollution
Social: labour practices, community impact, human rights
Governance: board structure, transparency, anti-corruption practices', NULL, NULL, NULL, 44, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'bb8e44bd-55e5-43be-adb8-622abd9ed640', '{"blocks": [{"id": "edm-u1-44-q-1", "text": "What is meant by ESG?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-44-a-1", "text": "Environmental, Social, and Governance — a framework to evaluate a company''s/investment''s sustainability and ethical impact:", "type": "text", "style": "paragraph"}, {"id": "edm-u1-44-a-2", "type": "bulletList", "items": ["Environmental: climate impact, resource use, pollution", "Social: labour practices, community impact, human rights", "Governance: board structure, transparency, anti-corruption practices"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('b8fac456-2f86-4597-bd12-2eb1d07486d5', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'What is a Green Bond?', '', 'A fixed-income debt instrument whose proceeds are earmarked to fund projects with positive environmental benefits (renewable energy, clean transportation, energy efficiency). Structurally like a normal bond; what differs is the use of proceeds and reporting requirements.', NULL, NULL, NULL, 45, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'bb8e44bd-55e5-43be-adb8-622abd9ed640', '{"blocks": [{"id": "edm-u1-45-q-1", "text": "What is a Green Bond?", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-45-a-1", "text": "A fixed-income debt instrument whose proceeds are earmarked to fund projects with positive environmental benefits (renewable energy, clean transportation, energy efficiency). Structurally like a normal bond; what differs is the use of proceeds and reporting requirements.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('d9471cfb-24ff-4414-8146-9c080ccd829f', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'State the key characteristics of Green Bonds.', '', 'Proceeds are ring-fenced for environmentally beneficial projects
Requires disclosure/reporting on use of funds and impact
Often subject to external review/certification
Structurally similar to conventional bonds
Attracts sustainability-conscious investors', NULL, NULL, NULL, 46, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'bb8e44bd-55e5-43be-adb8-622abd9ed640', '{"blocks": [{"id": "edm-u1-46-q-1", "text": "State the key characteristics of Green Bonds.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-46-a-1", "type": "numberList", "items": ["Proceeds are ring-fenced for environmentally beneficial projects", "Requires disclosure/reporting on use of funds and impact", "Often subject to external review/certification", "Structurally similar to conventional bonds", "Attracts sustainability-conscious investors"]}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('9c8dd7a5-3e61-4f0e-9b91-b0d20887d9c2', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Distinguish between ESG and Green Bonds.', '', 'Basis | ESG | Green Bonds
Nature | A broad evaluation framework | A specific debt instrument
Scope | Environmental + Social + Governance | Primarily environmental (project-linked)
Application | Companies/investments generally | Specifically to bond issuance
Relationship | Broader framework | One tool supporting the "E" in ESG

Exam Tip: Green Bonds are a specific financing instrument; ESG is a broader evaluative framework.', NULL, NULL, NULL, 47, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'bb8e44bd-55e5-43be-adb8-622abd9ed640', '{"blocks": [{"id": "edm-u1-47-q-1", "text": "Distinguish between ESG and Green Bonds.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-47-a-1", "rows": [["Basis", "ESG", "Green Bonds"], ["Nature", "A broad evaluation framework", "A specific debt instrument"], ["Scope", "Environmental + Social + Governance", "Primarily environmental (project-linked)"], ["Application", "Companies/investments generally", "Specifically to bond issuance"], ["Relationship", "Broader framework", "One tool supporting the \"E\" in ESG"]], "type": "table"}, {"id": "edm-u1-47-a-2", "bold": true, "text": "Exam Tip: Green Bonds are a specific financing instrument; ESG is a broader evaluative framework.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
('ae0fd214-4837-4394-b5db-85a02bb0bd6c', '4942b243-3eda-4100-9200-942a29e98d11', 'flashcard', 'Discuss the relevance of ESG and Green Bonds to sustainable finance.', '', 'Central to sustainable finance, aligning capital allocation with long-term environmental/social outcomes. Green Bonds let governments and corporates raise capital explicitly for climate-positive projects. Exam Tip: Closing line — "ESG and Green Bonds represent the debt market''s evolving contribution to sustainable and responsible economic growth."', NULL, NULL, NULL, 48, true, 'University Exam', NULL, NULL, NULL, 'a2aabef7-6d37-4560-b100-28902f5cd163', 'bb8e44bd-55e5-43be-adb8-622abd9ed640', '{"blocks": [{"id": "edm-u1-48-q-1", "text": "Discuss the relevance of ESG and Green Bonds to sustainable finance.", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '{"blocks": [{"id": "edm-u1-48-a-1", "text": "Central to sustainable finance, aligning capital allocation with long-term environmental/social outcomes. Green Bonds let governments and corporates raise capital explicitly for climate-positive projects. Exam Tip: Closing line — \"ESG and Green Bonds represent the debt market''s evolving contribution to sustainable and responsible economic growth.\"", "type": "text", "style": "paragraph"}], "version": 1}'::jsonb, '2026-09-09 17:19:00.009132+00', '2026-09-09 17:19:00.009132+00'),
