('61b8295b-c4e4-4d00-ba46-745195691d3e', 'e9c8f886-9fbb-4b24-980c-2cf403873185', 'pyq', 'Advertising - October 2025', 'Practice PYQs and Ace your Endsems.', '', 2025, 'https://h36y6svq.us-east.insforge.app/api/storage/buckets/cue-pyqs/objects/e9c8f886-9fbb-4b24-980c-2cf403873185%2F2025%2F6bff1f12-abc8-4db0-80e0-f590c5434ea7-advertising-2025.pdf?v=2206df42160b4952a4d3267783e2dc50', 'e9c8f886-9fbb-4b24-980c-2cf403873185/2025/6bff1f12-abc8-4db0-80e0-f590c5434ea7-advertising-2025.pdf', 1, true, 'Regular Examination', 'Advertising_2025.pdf', 174150, '6bff1f12-abc8-4db0-80e0-f590c5434ea7', NULL, NULL, NULL, NULL, '2026-09-17 04:58:31.466668+00', '2026-09-17 12:26:26.200143+00'),
